<script setup>import { onMounted,onUnmounted,ref } from 'vue'; import { useRoute } from 'vue-router'; import api from '@/api/client'; import StatusBadge from '@/components/StatusBadge.vue'; import StatusTimeline from '@/components/StatusTimeline.vue'; const route=useRoute(); const data=ref(null); const error=ref(''); let timer; async function load(){try{data.value=(await api.get(`/public/track/${route.params.code}`)).data.data}catch(e){error.value=e.response?.data?.message||'Data tidak ditemukan.'}} onMounted(()=>{load();timer=setInterval(load,15000)});onUnmounted(()=>clearInterval(timer))</script><template><section><p v-if="error" class="text-red-800">{{error}}</p><div v-else-if="!data">Memuat data...</div><article v-else><h1>Antrian {{String(data.queue_number).padStart(3,'0')}}</h1><StatusBadge :status="data.status"/><p>{{data.vehicle.brand}} {{data.vehicle.model}} · {{data.vehicle.plate_masked}}</p><p v-if="data.public_note">{{data.public_note}}</p><StatusTimeline :items="data.timeline"/><h2 class="text-lg font-bold text-forest">Jasa</h2><ul><li v-for="name in data.services" :key="name">{{name}}</li></ul><p v-if="data.total !== null">Total: Rp {{data.total.toLocaleString('id-ID')}}</p></article></section></template>